function validate([logs, k]) {
  if (!Array.isArray(logs) || logs.length < 1 || logs.length > 10000) return 'logs needs 1 to 10000 entries.';
  const seen = new Map();
  for (const entry of logs) {
    if (!Array.isArray(entry) || entry.length !== 2) return 'Each log is [id, time].';
    const [id, time] = entry;
    if (!Number.isInteger(id) || id < 0 || id > 1e9) return 'Each id is an integer from 0 to 10^9.';
    if (!Number.isInteger(time) || time < 1 || time > 1e5) return 'Each time is an integer from 1 to 10^5.';
    if (!seen.has(id)) seen.set(id, new Set());
    seen.get(id).add(time);
  }
  let most = 0;
  for (const minutes of seen.values()) most = Math.max(most, minutes.size);
  if (!Number.isInteger(k) || k < most || k > 1e5) return `k must be at least the largest UAM (${most}) and at most 10^5.`;
  return null;
}

