function findingUsersActiveMinutes(logs, k) {
  const minutesByUser = new Map();
  for (const [id, time] of logs) {
    if (!minutesByUser.has(id)) {
      minutesByUser.set(id, new Set());
    }
    minutesByUser.get(id).add(time);
  }

  const answer = new Array(k).fill(0);
  for (const minutes of minutesByUser.values()) {
    answer[minutes.size - 1]++;
  }
  return answer;
}

