function findingUsersActiveMinutes(logs, k) {
  // Sort by user then minute; each user's UAM is the number of minute changes in their run.
  const sorted = logs.map(entry => entry.slice()).sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const result = Array.from({ length: k }, () => 0);
  let i = 0;
  while (i < sorted.length) {
    let j = i;
    let distinct = 0;
    while (j < sorted.length && sorted[j][0] === sorted[i][0]) {
      if (j === i || sorted[j][1] !== sorted[j - 1][1]) distinct++;
      j++;
    }
    result[distinct - 1] += 1;
    i = j;
  }
  return result;
}

