function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 2000 : 1 + pick(10);
  const users = size === 'large' ? [5, 40, 300, 2000][pick(4)] : 1 + pick(4);
  const minutes = size === 'large' ? [50, 1000, 100000][pick(3)] : 1 + pick(6);
  const ids = Array.from({ length: users }, (_, u) => (rand() < 0.3 ? pick(1000000001) : u));
  const logs = Array.from({ length: n }, () => [ids[pick(users)], 1 + pick(minutes)]);
  const seen = new Map();
  for (const [id, time] of logs) {
    if (!seen.has(id)) seen.set(id, new Set());
    seen.get(id).add(time);
  }
  const most = Math.max(...[...seen.values()].map(s => s.size));
  const k = Math.min(most + pick(size === 'large' ? 40 : 3), 2000);
  return [logs, k];
}
